use verus::prelude::*;

// Reverse a Vec<char> by walking its .iter().rev().
// SPECIFICATION:
//
//   • The output has the same length as the input.
//   • For every index i in 0..input.len(),
//       output[i] == input[input.len() - 1 - i]
//
#[requires(true)]
#[ensures(result.len() == arr.len())]
#[ensures(
    forall|i: int|
        0 <= i && i < arr@.len() ==>
            result@[i] == arr@[arr@.len() - 1 - i]
)]
fn yarra(arr: &Vec<char>) -> Vec<char> {
    let mut outarr = Vec::with_capacity(arr.len());

    // Loop over arr in reverse order, pushing each character.
    // INV: outarr contains exactly the prefix of the reversed array
    //      of length outarr.len().
    // DECREASE: the number of remaining elements to iterate =
    //           arr.len() - outarr.len().
    #[invariant(outarr@.len() <= arr@.len())]
    #[invariant(
        forall|i: int|
            0 <= i && i < outarr@.len() ==>
                outarr@[i] == arr@[arr@.len() - 1 - i]
    )]
    #[decreases(arr.len() - outarr.len())]
    for &ch in arr.iter().rev() {
        outarr.push(ch);
    }

    outarr
}

